class Solution:
    def latestTimeCatchBus(self, buses: list[int], passengers: list[int], capacity: int) -> int:
        buses.sort()
        passengers.sort()
        j = 0
        m = len(passengers)
        for bus in buses:
            cap = capacity
            while cap > 0 and j < m and passengers[j] <= bus:
                j += 1
                cap -= 1
        last_time = buses[-1] if cap > 0 else passengers[j - 1]
        pset = set(passengers)
        while last_time in pset:
            last_time -= 1
        return last_time

class Solution {
public:
    int latestTimeCatchBus(std::vector<int>& buses, std::vector<int>& passengers, int capacity) {
        std::sort(buses.begin(), buses.end());
        std::sort(passengers.begin(), passengers.end());
        int j = 0, m = passengers.size(), cap = 0;
        for (int bus : buses) {
            cap = capacity;
            while (cap > 0 && j < m && passengers[j] <= bus) {
                j++;
                cap--;
            }
        }
        int last_time = cap > 0 ? buses.back() : passengers[j - 1];
        std::unordered_set<int> pset(passengers.begin(), passengers.end());
        while (pset.count(last_time)) {
            last_time--;
        }
        return last_time;
    }
};

class Solution {
    public int latestTimeCatchBus(int[] buses, int[] passengers, int capacity) {
        java.util.Arrays.sort(buses);
        java.util.Arrays.sort(passengers);
        int j = 0, m = passengers.length, cap = 0;
        for (int bus : buses) {
            cap = capacity;
            while (cap > 0 && j < m && passengers[j] <= bus) {
                j++;
                cap--;
            }
        }
        int lastTime = cap > 0 ? buses[buses.length - 1] : passengers[j - 1];
        java.util.Set<Integer> pset = new java.util.HashSet<>();
        for (int p : passengers) pset.add(p);
        while (pset.contains(lastTime)) {
            lastTime--;
        }
        return lastTime;
    }
}

